package com.pulsepay.audit;
import com.pulsepay.security.MerchantPrincipal; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/audit-logs") public class AuditController { private final JdbcTemplate db; public AuditController(JdbcTemplate db){this.db=db;} @GetMapping public List<Map<String,Object>> list(@AuthenticationPrincipal MerchantPrincipal p){return db.query("select action,resource_type,resource_id,created_at from audit_logs where merchant_id=? order by created_at desc limit 200",(rs,i)->Map.of("action",rs.getString(1),"resource_type",rs.getString(2),"resource_id",Optional.ofNullable(rs.getString(3)).orElse(""),"created_at",rs.getTimestamp(4).toInstant().toString()),p.merchantId());}}
